const layers=[['01 / 기존 벽','벽 온도와 습도, 누수 여부를 확인하고 곰팡이 제거와 건조를 진행합니다.'],['02 / 단열층','폼본드 전면 접착으로 단열재를 밀착하고, 이음새까지 마감합니다.'],['03 / 항균 코팅','상품 구성에 따라 박테론 항균 코팅을 1회 또는 2회 적용합니다.'],['04 / 도배 마감','합지 또는 실크 도배로 마무리하고, 열화상 검수 후 리포트를 전달합니다.']];
document.querySelectorAll('[data-layer]').forEach(button=>{button.setAttribute('aria-pressed',button.classList.contains('active'));button.addEventListener('click',()=>{document.querySelectorAll('[data-layer]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');const data=layers[Number(button.dataset.layer)];document.getElementById('layer-number').textContent=data[0];document.getElementById('layer-text').textContent=data[1]})});
const plan=document.getElementById('plan'),area=document.getElementById('area'),estimate=document.getElementById('estimate'),tax=document.getElementById('tax');
function updateEstimate(){const size=Number(area.value);if(!Number.isFinite(size)||size<=0||size>1000){estimate.textContent='면적 확인';tax.textContent='0.1~1,000㎡ 사이로 입력해주세요.';return}const value=Math.max(450000,Math.round(Number(plan.value)*size));estimate.innerHTML=value.toLocaleString('ko-KR')+'<small>원</small>';tax.textContent='VAT 포함 '+Math.round(value*1.1).toLocaleString('ko-KR')+'원'+(Number(plan.value)*size<450000?' · 최소 시공 금액 적용':'')}
[plan,area].forEach(el=>el.addEventListener('input',updateEstimate));
document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>{plan.value=b.dataset.plan;updateEstimate();document.getElementById('calculator').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
document.getElementById('inquiry').addEventListener('submit',event=>{event.preventDefault();const region=document.getElementById('region').value.trim(),problem=document.getElementById('problem').value.trim();if(!region||!problem)return;document.getElementById('inquiry-text').textContent='[팡아웃 상담 요청]\n시공 지역: '+region+'\n벽 상태: '+problem+'\n관심 상품: '+plan.selectedOptions[0].text+'\n\n준비할 사진\n1. 문제 부위 전체\n2. 벽 표면 가까이\n3. 창문과 모서리를 포함한 주변 모습';document.getElementById('inquiry-result').hidden=false;document.getElementById('copy-status').textContent='';});
document.getElementById('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById('inquiry-text').textContent);document.getElementById('copy-status').textContent='복사했습니다.'}catch{document.getElementById('copy-status').textContent='위 내용을 선택해 복사해주세요.'}});
